// Switched from Web Audio API oscillators to plain <audio> elements with a
// pre-rendered sound after the oscillator approach kept failing silently in
// Safari — the tab's audio indicator lit up (so *something* was "playing"),
// but nothing was actually audible, even on a direct test-button click with
// system volume/output confirmed fine. A plain <audio> element uses the same
// playback pathway as any normal media on the page, which is known-working on
// the affected machine (e.g. video audio).

const DING_SRC = "data:audio/wav;base64,";
const CHIME_SRC = "data:audio/wav;base64,";

let dingEl: HTMLAudioElement | null = null;
let chimeEl: HTMLAudioElement | null = null;

function getDingElement(): HTMLAudioElement {
  if (!dingEl) {
    dingEl = new Audio(DING_SRC);
    dingEl.preload = "auto";
  }
  return dingEl;
}

function getChimeElement(): HTMLAudioElement {
  if (!chimeEl) {
    chimeEl = new Audio(CHIME_SRC);
    chimeEl.preload = "auto";
  }
  return chimeEl;
}

function primeElement(el: HTMLAudioElement): void {
  const playPromise = el.play();
  if (playPromise && typeof playPromise.then === "function") {
    playPromise
      .then(() => {
        el.pause();
        el.currentTime = 0;
      })
      .catch(() => {
        // Still locked — will retry on the next gesture/visibility event.
      });
  } else {
    el.pause();
    el.currentTime = 0;
  }
}

// Safari (and most browsers to some degree) only reliably allow a timer-driven
// sound (a pomodoro/break finishing on its own) to actually play once each
// <audio> element has been primed from inside a real user gesture. Call this
// from click handlers so later timer-driven sounds aren't silently blocked.
export function unlockAudio(): void {
  primeElement(getDingElement());
  primeElement(getChimeElement());
}

function play(el: HTMLAudioElement): void {
  try {
    el.currentTime = 0;
    el.play().catch(() => {
      // Autoplay still blocked in this context — nothing more we can do here;
      // the Notification fallback (see notify.ts) covers this case.
    });
  } catch {
    // Audio unavailable in this environment — fail silently.
  }
}

export function playDing(): void {
  play(getDingElement());
}

export function playChime(): void {
  play(getChimeElement());
}
